#!/usr/bin/env python3
"""Helper script for third_party/istio/update-istio.sh to process Istio manifests."""

import sys
import yaml


def process_manifests(full_file, config_file, values_file, out_file, dst_file):
  with open(full_file, "r") as f:
    raw_content = f.read()

  docs_text = raw_content.split("\n---\n")
  out_docs = []

  for doc_str in docs_text:
    if not doc_str.strip():
      continue
    try:
      doc_obj = yaml.safe_load(doc_str)
    except Exception:
      out_docs.append(doc_str)
      continue

    if (
        doc_obj
        and isinstance(doc_obj, dict)
        and doc_obj.get("kind") == "ConfigMap"
        and doc_obj.get("metadata", {}).get("name") == "istio-sidecar-injector"
    ):
      cdata = doc_obj.get("data", {})
      if "config" in cdata:
        with open(config_file, "w") as f:
          f.write(cdata["config"])
      if "values" in cdata:
        with open(values_file, "w") as f:
          f.write(cdata["values"])

      doc_obj["data"]["config"] = "HELM_PLACEHOLDER_CONFIG"
      doc_obj["data"]["values"] = "HELM_PLACEHOLDER_VALUES"
      dumped = yaml.dump(doc_obj, sort_keys=False)
      dumped = dumped.replace(
          "HELM_PLACEHOLDER_CONFIG",
          '|-\n{{ .Files.Get "files/istio-config.yaml" | nindent 4 }}',
      )
      dumped = dumped.replace(
          "HELM_PLACEHOLDER_VALUES",
          '|-\n{{ .Files.Get "files/istio-values.json" | nindent 4 }}',
      )
      dumped = dumped.replace("'|-\n", "|-\n")
      out_docs.append(dumped)
    else:
      out_docs.append(doc_str)

  processed_yaml = "\n---\n".join(out_docs)

  with open(out_file, "w") as f:
    f.write(processed_yaml)

  # Now prepare istio-generated.yaml for Helm chart embedding
  snippet = """
      {{- if .Values.istio.additionalExtensionProviders }}
      {{- tpl (toYaml .Values.istio.additionalExtensionProviders | replace "\\n      (" " (" | replace "\\n      \\"" " \\"" | replace "\\n      '" " '") . | nindent 4 }}
      {{- end }}"""

  if (
      "extensionProviders: []" in processed_yaml
      and "additionalExtensionProviders" not in processed_yaml
  ):
    processed_yaml = processed_yaml.replace(
        "extensionProviders: []", "extensionProviders:" + snippet, 1
    )
  elif (
      "extensionProviders:" in processed_yaml
      and "additionalExtensionProviders" not in processed_yaml
  ):
    processed_yaml = processed_yaml.replace(
        "extensionProviders:", "extensionProviders:" + snippet, 1
    )

  old_str = (
      'template: "{{'
      ' Template_Version_And_Istio_Version_Mismatched_Check_Installation }}"'
  )
  new_str = (
      "template:"
      ' "Template_Version_And_Istio_Version_Mismatched_Check_Installation"'
  )
  if old_str in processed_yaml:
    processed_yaml = processed_yaml.replace(old_str, new_str)

  header = """{{- if eq .Values.use_istio "true" }}
# Generated by update-istio.sh. DO NOT EDIT!
# ---------------------------------------------------------
# Istio System Manifests
# ---------------------------------------------------------
"""
  footer = "\n{{- end }}\n"

  with open(dst_file, "w") as f:
    f.write(header + processed_yaml + footer)

  print(f"Successfully processed {full_file} -> {dst_file}")


if __name__ == "__main__":
  if len(sys.argv) < 6:
    print(
        "Usage: process_istio_manifest.py <full_file> <config_file>"
        " <values_file> <out_file> <dst_file>",
        file=sys.stderr,
    )
    sys.exit(1)
  process_manifests(
      sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5]
  )
